/// <summary>
/// HSMobileOpsDeviceWorkSvc response. Items: the worker's work saved from other devices (listWork). DisabledModules: modules switched off for this app version - on every answer, so the app keeps its copy current.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDeviceWorkResponse
{
    boolean    success;
    str        errorCode;
    str        message;
    int        stored;
    boolean    deviceCleanup;
    int        finishedJournalDays;
    int        orderHistoryDays;
    int        oldWorkDays;
    str        fullResyncAfterUtc;
    List       items;
    List       disabledModules;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Stored')]
public int parmStored(int _value = stored)
{
    stored = _value;
    return stored;
}

[DataMemberAttribute('DeviceCleanup')]
public boolean parmDeviceCleanup(boolean _value = deviceCleanup)
{
    deviceCleanup = _value;
    return deviceCleanup;
}

[DataMemberAttribute('FinishedJournalDays')]
public int parmFinishedJournalDays(int _value = finishedJournalDays)
{
    finishedJournalDays = _value;
    return finishedJournalDays;
}

[DataMemberAttribute('OrderHistoryDays')]
public int parmOrderHistoryDays(int _value = orderHistoryDays)
{
    orderHistoryDays = _value;
    return orderHistoryDays;
}

/// <summary>
/// Mobile item snapshot, Ask all devices to full re-sync: a device whose last full download
/// is older does one. Blank when never asked.
/// </summary>
[DataMemberAttribute('FullResyncAfterUtc')]
public str parmFullResyncAfterUtc(str _value = fullResyncAfterUtc)
{
    fullResyncAfterUtc = _value;
    return fullResyncAfterUtc;
}

[DataMemberAttribute('OldWorkDays')]
public int parmOldWorkDays(int _value = oldWorkDays)
{
    oldWorkDays = _value;
    return oldWorkDays;
}

[DataMemberAttribute('Items'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsDeviceWorkRow))]
public List parmItems(List _value = items)
{
    items = _value;
    return items;
}

[DataMemberAttribute('DisabledModules'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsModuleSwitchRow))]
public List parmDisabledModules(List _value = disabledModules)
{
    disabledModules = _value;
    return disabledModules;
}
